interface ArrayLike<T> extends Array<T> {}

function quicksort<T>(arr: ArrayLike<T>): ArrayLike<T> {
    const [left, mid, right] = arr.reduce<[ArrayLike<T>, ArrayLike<T>, ArrayLike<T>>>(
        ([left, mid, right], value) => {
            if (value < mid) {
                mid = [...mid, value];
            } else if (value > mid) {
                right = [...right, value];
            } else {
                mid = [...mid, value];
            }
            return [left, mid, right];
        },
        [[], [], []]
    );

    if (left.length > 1) {
        quicksort(left);
    }
    if (right.length > 1) {
        quicksort(right);
    }

    return [...left, ...mid, ...right];
}

// Example usage:
